99: fn parse_date(value: &str, field: &str) -> Result<Date, RestError> {
100:     Date::parse(
101:         value,
102:         &time::macros::format_description!("[year]-[month]-[day]"),
103:     )
104:     .map_err(|_| {
105:         RestError::new(
106:             StatusCode::UNPROCESSABLE_ENTITY,
107:             "validation",
108:             format!("{field} must be YYYY-MM-DD"),
109:         )
110:     })
111: }
112: 
113: /// `YYYY-MM` → the exact calendar month. Half-open end is derived, never
114: /// guessed: February and the 31-day months must both be right.
115: fn parse_period(value: &str) -> Result<(Date, Date), RestError> {
116:     let invalid = || {
117:         RestError::new(
118:             StatusCode::UNPROCESSABLE_ENTITY,
119:             "validation",
120:             "period must be YYYY-MM",
121:         )
122:     };
123:     let (year, month) = value.split_once('-').ok_or_else(invalid)?;
124:     // Shape first. `"26-07"` otherwise parses as year 26 AD and produces a
125:     // confusing downstream "missing payroll rate for 0026-07-31" instead of
126:     // naming the malformed input.
127:     if year.len() != 4
128:         || month.len() != 2
129:         || !year.bytes().all(|b| b.is_ascii_digit())
130:         || !month.bytes().all(|b| b.is_ascii_digit())
131:     {
132:         return Err(invalid());
133:     }
134:     let year: i32 = year.parse().map_err(|_| invalid())?;
135:     let month: u8 = month.parse().map_err(|_| invalid())?;
136:     let month = Month::try_from(month).map_err(|_| invalid())?;
137:     let start = Date::from_calendar_date(year, month, 1).map_err(|_| invalid())?;
138:     let end = start
139:         .replace_day(start.month().length(start.year()))
140:         .map_err(|_| invalid())?;
141:     Ok((start, end))
142: }
