412: pub async fn close_attendance_in_tx(
413:     tx: &mut Transaction<'_, Postgres>,
414:     run_id: Uuid,
415:     actor: Uuid,
416:     now: OffsetDateTime,
417: ) -> Result<Value, LifecycleError> {
418:     let Some(run) = run_head(tx, run_id, true).await? else {
419:         return Err(LifecycleError::NotFound);
420:     };
421:     if !CLOSEABLE.contains(&run.status.as_str()) {
422:         return Err(invalid_state("close attendance for", &run.status));
423:     }
424:     // Recomputed HERE, inside the closing transaction, behind the run's
425:     // FOR UPDATE lock — never read back from a verdict computed earlier
426:     // (`close_receipt` is the attestation record this close writes, never an
427:     // input to it). A verdict trusted later is a TOCTOU hole.
428:     let preflight = preflight_for(tx, &run).await?;
429:     if !preflight.can_close {
430:         return Err(LifecycleError::PreflightBlocked(preflight));
431:     }
432: 
433:     let receipt = json!({
434:         "checks": serde_json::to_value(&preflight.checks).map_err(json_internal)?,
435:         "attested_by": actor,
436:         "attested_at": now.format(&Iso8601::DEFAULT).map_err(|err| {
437:             LifecycleError::Validation(format!("failed to format attestation time: {err}"))
438:         })?,
439:     });
440:     sqlx::query(
441:         "UPDATE payroll_draft_runs \
442:          SET status = 'ATTENDANCE_CLOSED', close_receipt = $2, updated_at = now() \
443:          WHERE id = $1",
444:     )
445:     .bind(run_id)
446:     .bind(&receipt)
447:     .execute(tx.as_mut())
448:     .await?;
449:     Ok(receipt)
450: }
