958: pub async fn decide_run_in_tx(
959:     tx: &mut Transaction<'_, Postgres>,
960:     run_id: Uuid,
961:     actor: Uuid,
962:     decision: &str,
963:     reason: Option<&str>,
964: ) -> Result<(), LifecycleError> {
965:     let Some(run) = run_head(tx, run_id, true).await? else {
966:         return Err(LifecycleError::NotFound);
967:     };
968:     if run.status != "SUBMITTED" {
969:         return Err(invalid_state("decide", &run.status));
970:     }
971:     if run.submitted_by == Some(actor) {
972:         return Err(LifecycleError::SodViolation);
973:     }
974:     match decision {
975:         "APPROVE" => {
976:             sqlx::query(
977:                 "UPDATE payroll_draft_runs \
978:                  SET status = 'APPROVED', decided_by = $2, decided_at = now(), \
979:                      decision_reason = $3, approved_by = $2, approved_at = now(), \
980:                      updated_at = now() \
981:                  WHERE id = $1",
982:             )
983:             .bind(run_id)
984:             .bind(actor)
985:             .bind(reason)
986:             .execute(tx.as_mut())
987:             .await?;
988:         }
989:         "REJECT" => {
990:             if reason.is_none_or(|r| r.trim().is_empty()) {
991:                 return Err(LifecycleError::Validation(
992:                     "a reason is required to reject a payroll run".to_owned(),
993:                 ));
994:             }
995:             sqlx::query(
996:                 "UPDATE payroll_draft_runs \
997:                  SET status = 'REJECTED', decided_by = $2, decided_at = now(), \
998:                      decision_reason = $3, updated_at = now() \
999:                  WHERE id = $1",
1000:             )
1001:             .bind(run_id)
1002:             .bind(actor)
1003:             .bind(reason)
1004:             .execute(tx.as_mut())
1005:             .await?;
1006:         }
1007:         other => {
1008:             return Err(LifecycleError::Validation(format!(
1009:                 "unknown decision: {other}"
1010:             )));
1011:         }
1012:     }
1013:     Ok(())
1014: }
