851: pub async fn resolve_exception_in_tx(
852:     tx: &mut Transaction<'_, Postgres>,
853:     run_id: Uuid,
854:     exception_id: Uuid,
855:     actor: Uuid,
856:     action: &str,
857:     reason: Option<&str>,
858: ) -> Result<PayrollException, LifecycleError> {
859:     let Some(run) = run_head(tx, run_id, true).await? else {
860:         return Err(LifecycleError::NotFound);
861:     };
862:     if run.status != "CALCULATED" {
863:         return Err(invalid_state("resolve exceptions for", &run.status));
864:     }
865:     let new_status = match action {
866:         "CONFIRM" => "CONFIRMED",
867:         "HOLD" => {
868:             if reason.is_none_or(|r| r.trim().is_empty()) {
869:                 return Err(LifecycleError::Validation(
870:                     "a reason is required to hold an exception to the next run".to_owned(),
871:                 ));
872:             }
873:             "HELD"
874:         }
875:         other => {
876:             return Err(LifecycleError::Validation(format!(
877:                 "unknown resolve action: {other}"
878:             )));
879:         }
880:     };
881:     let current: Option<String> = sqlx::query_scalar(
882:         "SELECT status FROM payroll_run_exceptions WHERE id = $1 AND run_id = $2 FOR UPDATE",
883:     )
884:     .bind(exception_id)
885:     .bind(run_id)
886:     .fetch_optional(tx.as_mut())
887:     .await?;
888:     match current.as_deref() {
889:         None => return Err(LifecycleError::NotFound),
890:         Some("OPEN") => {}
891:         Some(_) => return Err(LifecycleError::AlreadyResolved),
892:     }
893:     let row = sqlx::query(
894:         "UPDATE payroll_run_exceptions \
895:          SET status = $3, resolved_by = $4, resolved_at = now(), resolved_reason = $5, \
896:              updated_at = now() \
897:          WHERE id = $1 AND run_id = $2 \
898:          RETURNING id, run_id, line_id, employee_id, employee_display_name, kind, severity, \
899:                    amount_delta_won, summary_ko, detail, linked_refs, status, resolved_by, \
900:                    resolved_at, resolved_reason, carried_from_run_id, created_at",
901:     )
902:     .bind(exception_id)
903:     .bind(run_id)
904:     .bind(new_status)
905:     .bind(actor)
906:     .bind(reason)
907:     .fetch_one(tx.as_mut())
908:     .await?;
909:     exception_from_row(&row)
910: }
