912: pub async fn exception_counts_in_tx(
913:     tx: &mut Transaction<'_, Postgres>,
914:     run_id: Uuid,
915: ) -> Result<(i64, i64), LifecycleError> {
916:     let row = sqlx::query(
917:         "SELECT COUNT(*)::BIGINT AS total, \
918:                 COUNT(*) FILTER (WHERE status = 'OPEN')::BIGINT AS open \
919:          FROM payroll_run_exceptions WHERE run_id = $1",
920:     )
921:     .bind(run_id)
922:     .fetch_one(tx.as_mut())
923:     .await?;
924:     Ok((row.try_get("open")?, row.try_get("total")?))
925: }
